// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/jetbrains-mono";
import "@fontsource/noto-sans-kr";

export const jetbrainsMono = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { jetbrainsMono, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "ASCII";

/**
 * ASCII 아스키 — pictures drawn in characters. The signature is an ASCII
 * density-field renderer on canvas: a brightness function (a lit sphere, a
 * sine landscape) is sampled on a character grid and each cell is mapped to
 * a char on the ramp .:-=+*#%@, then drawn green-on-black like a phosphor
 * terminal. Every value is NaN-guarded (clamped radii, Number.isFinite
 * fallback) so a single bad sample never crashes the page.
 *
 * `.ascii-js` is added on mount so the no-JS markup is the finished page:
 * the canvas replaced by a static ASCII understudy <pre>, the wordmark lit.
 */
export default function AsciiPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const sphereRef = useRef<HTMLCanvasElement | null>(null);
  const landRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("ascii-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "ascii" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // ASCII sphere renderer. brightness = diffuse shading of a lit sphere,
  // mapped to the char ramp. Slowly rotating light source. NaN-safe.
  useEffect(() => {
    const canvas = sphereRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const RAMP = " .:-=+*#%@";
    const COLS = 46;
    const ROWS = 22;
    let w = 0;
    let h = 0;
    let dpr = 1;

    const resize = () => {
      dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
      const rect = canvas.getBoundingClientRect();
      w = Math.max(1, Math.round(rect.width));
      h = Math.max(1, Math.round(rect.height));
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    };
    resize();

    let raf = 0;
    let t = 0;
    const fontPx = 13;

    const render = () => {
      t += reduced ? 0 : 0.012;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = "#020604";
      ctx.fillRect(0, 0, w, h);
      ctx.font = `${fontPx}px var(--font-jetbrains-mono), "JetBrains Mono", ui-monospace, monospace`;
      ctx.font = `${fontPx}px "JetBrains Mono", ui-monospace, monospace`;
      ctx.textBaseline = "top";

      const cellW = w / COLS;
      const cellH = h / ROWS;
      // light direction (normalized), slowly orbiting
      const lx = Math.cos(t * 0.6);
      const ly = -0.5;
      const lz = Math.sin(t * 0.6);
      const llen = Math.max(1e-6, Math.sqrt(lx * lx + ly * ly + lz * lz));

      for (let row = 0; row < ROWS; row++) {
        for (let col = 0; col < COLS; col++) {
          // normalized coords centered in the grid
          const u = (col / (COLS - 1)) * 2 - 1; // -1..1
          const v = (row / (ROWS - 1)) * 2 - 1; // -1..1
          // sphere: only inside the unit disc has shading
          const r2 = u * u + v * v;
          if (r2 > 1) {
            ctx.fillStyle = "rgba(94, 255, 160, 0.05)";
            ctx.fillText(" ", col * cellW, row * cellH);
            continue;
          }
          // z on the front hemisphere
          const z = Math.sqrt(Math.max(0, 1 - r2));
          // surface normal = (u, -v mapping to y up, z)
          const nx = u;
          const ny = -v;
          const dot = (nx * lx + ny * ly + z * lz) / llen;
          let bright = dot; // -1..1
          if (!Number.isFinite(bright)) bright = 0;
          // ambient + diffuse, clamp 0..1
          let intensity = 0.12 + 0.88 * Math.max(0, bright);
          if (!Number.isFinite(intensity)) intensity = 0;
          intensity = Math.max(0, Math.min(1, intensity));
          const idx = Math.min(
            RAMP.length - 1,
            Math.max(0, Math.round(intensity * (RAMP.length - 1))),
          );
          const ch = RAMP[idx];
          // edge of the disc reads dimmer; core reads brighter green
          const edgeFade = Math.max(0, 1 - r2);
          const alpha = 0.25 + 0.75 * edgeFade;
          ctx.fillStyle = `rgba(94, 255, 160, ${alpha.toFixed(3)})`;
          ctx.fillText(ch, col * cellW, row * cellH);
        }
      }
      if (!reduced) raf = requestAnimationFrame(render);
    };
    render();

    const onResize = () => {
      resize();
      if (reduced) render();
    };
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  // ASCII sine landscape renderer. brightness = height of a sum of sines,
  // mapped to the char ramp, scrolling horizontally. NaN-safe.
  useEffect(() => {
    const canvas = landRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const RAMP = " .:-=+*#%@";
    const COLS = 70;
    const ROWS = 20;
    let w = 0;
    let h = 0;
    let dpr = 1;

    const resize = () => {
      dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
      const rect = canvas.getBoundingClientRect();
      w = Math.max(1, Math.round(rect.width));
      h = Math.max(1, Math.round(rect.height));
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    };
    resize();

    let raf = 0;
    let t = 0;
    const fontPx = 12;

    const render = () => {
      t += reduced ? 0 : 0.03;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = "#020604";
      ctx.fillRect(0, 0, w, h);
      ctx.font = `${fontPx}px "JetBrains Mono", ui-monospace, monospace`;
      ctx.textBaseline = "top";

      const cellW = w / COLS;
      const cellH = h / ROWS;

      for (let row = 0; row < ROWS; row++) {
        for (let col = 0; col < COLS; col++) {
          const u = col / (COLS - 1); // 0..1
          const v = row / (ROWS - 1); // 0..1
          // heightfield: a couple of sines traveling in u, perspective in v
          const wave =
            Math.sin((u * 6 - t) * 1.0) * 0.5 +
            Math.sin((u * 3 + v * 4 - t * 0.7) * 1.0) * 0.3 +
            Math.cos((v * 5 + t * 0.4) * 1.0) * 0.2;
          let hgt = (wave + 1) / 2; // 0..1
          if (!Number.isFinite(hgt)) hgt = 0;
          hgt = Math.max(0, Math.min(1, hgt));
          // perspective: rows further "back" (lower v) read dimmer
          const persp = 0.4 + 0.6 * v;
          let intensity = hgt * persp;
          if (!Number.isFinite(intensity)) intensity = 0;
          intensity = Math.max(0, Math.min(1, intensity));
          const idx = Math.min(
            RAMP.length - 1,
            Math.max(0, Math.round(intensity * (RAMP.length - 1))),
          );
          const ch = RAMP[idx];
          ctx.fillStyle = `rgba(94, 255, 160, ${(0.3 + 0.7 * hgt).toFixed(3)})`;
          ctx.fillText(ch, col * cellW, row * cellH);
        }
      }
      if (!reduced) raf = requestAnimationFrame(render);
    };
    render();

    const onResize = () => {
      resize();
      if (reduced) render();
    };
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${jetbrainsMono.variable} ${notoSansKR.variable} ascii-root`}
    >
      <div className="ascii-grid-bg" aria-hidden="true" />
      <div ref={revealRef} className="ascii-doc">
        <header className="ascii-hero" data-reveal="">
          <p className="as-kicker">
            <span lang="ko">아스키 아트 렌더러</span> · ASCII RENDERER · v.064
          </p>
          <h1 className="as-title" aria-label={TITLE}>
            <span aria-hidden="true" className="as-title__row">
              {TITLE.split("").map((ch, i) => (
                <span
                  key={i}
                  className="ascii-glyph"
                  style={{ "--as-i": i } as CSSProperties}
                >
                  {ch}
                </span>
              ))}
            </span>
            <span lang="ko" className="as-title__kr" aria-hidden="true">
              아스키
            </span>
          </h1>
          <p className="as-sub" data-reveal="">
            <span lang="ko">문자로 그린 그림.</span> Pictures drawn in characters —
            a density field mapped to{" "}
            <code className="as-ramp">.:-=+*#%@</code>.
          </p>
        </header>

        <section className="as-stage" aria-labelledby="as-sphere-title">
          <div className="as-sechead" data-reveal="">
            <p className="as-eyebrow">
              02 — <span lang="ko">구</span> · the sphere
            </p>
            <h2 id="as-sphere-title" className="as-secthead__title">
              lit sphere
            </h2>
            <p className="as-secthead__kr" lang="ko">
              빛이 도는 구 — 확산 음영을 문자로.
            </p>
          </div>
          <div className="as-frame" data-reveal="">
            {/* No-JS understudy: a static ASCII sphere the page ships with. */}
            <pre className="as-understudy" aria-hidden="true">{`        .....         
     .:=+*#%%*=:..     
   :=+*#%%@@@@%#*+=:.   
  =+*#%@@@@@@@@@@%#*+=  
 :*#%@@@@@@@@@@@@@@%#*: 
:+#%@@@@@@@@@@@@@@@@%#+:
=*%@@@@@@@@@@@@@@@@@@%*=
=+%@@@@@@@@@@@@@@@@@@%+=
 :*#%@@@@@@@@@@@@@@%#*: 
  =+*#%@@@@@@@@@@%#*+=  
   :=+*#%%@@@@%#*+=:.   
     .:=+*#%%*=:..     
        .....         `}</pre>
            <canvas
              ref={sphereRef}
              className="as-canvas"
              aria-label="ASCII 렌더: 빛이 도는 구. ASCII render: a lit sphere rotating under a moving light."
            />
            <p className="as-readout">
              <span lang="ko">확산 음영 → 문자 램프</span> · DIFFUSE → RAMP · 46×22
            </p>
          </div>
        </section>

        <section className="as-stage" aria-labelledby="as-land-title">
          <div className="as-sechead" data-reveal="">
            <p className="as-eyebrow">
              03 — <span lang="ko">파형</span> · the landscape
            </p>
            <h2 id="as-land-title" className="as-secthead__title">
              sine landscape
            </h2>
            <p className="as-secthead__kr" lang="ko">
              사인파 고도장이 흐르는 풍경.
            </p>
          </div>
          <div className="as-frame" data-reveal="">
            <pre className="as-understudy" aria-hidden="true">{`::::::::::::::::::::::::::::::::::::::::::::::::::::
:::::::-====---=---==----=-==---=-====---==---=-:::::
:::-=+*#%%%*+=--=+*#%%#*+=---=+*#%%%*+=--=+*#%%#+-:::
:-=*%@@@@@%#+:--+%@@@@@%#=:--+%@@@@@%#+:--+%@@@@@%*::
:=+%@@@@@@@%*:--+#@@@@@@@#+:-=*@@@@@@@%*:--+#@@@@@@@#:
:=*%@@@@@@@#=---=*@@@@@@@#=:-=*@@@@@@@#=---=*@@@@@@@#:
:-+#@@@@@@@*:----=#@@@@@@#=---=#@@@@@@@*:----=#@@@@@@#
:--+%@@@@@%#=-----=*%@@@%#=----=*%@@@%#=-----=*%@@@%#:
:::=*#%%%#*=:------:=*##*=:------:=*##*=:------:=*##*:
::::-----:::--------:::::--------:::::--------:::::--`}</pre>
            <canvas
              ref={landRef}
              className="as-canvas"
              aria-label="ASCII 렌더: 흐르는 사인파 풍경. ASCII render: a scrolling sine-wave landscape."
            />
            <p className="as-readout">
              <span lang="ko">고도장 → 문자 램프</span> · HEIGHTFIELD → RAMP · 70×20
            </p>
          </div>
        </section>

        <section className="as-how" aria-labelledby="as-how-title">
          <div className="as-sechead" data-reveal="">
            <p className="as-eyebrow">
              04 — <span lang="ko">방법</span> · how
            </p>
            <h2 id="as-how-title" className="as-secthead__title">
              the ramp
            </h2>
            <p className="as-secthead__kr" lang="ko">
              밝기 → 문자. 열 개의 문자로 명암을 그린다.
            </p>
          </div>
          <div className="as-ramp-row" data-reveal="" aria-hidden="true">
            <span className="as-ramp-ch">.</span>
            <span className="as-ramp-ch">:</span>
            <span className="as-ramp-ch">-</span>
            <span className="as-ramp-ch">=</span>
            <span className="as-ramp-ch">+</span>
            <span className="as-ramp-ch">*</span>
            <span className="as-ramp-ch">#</span>
            <span className="as-ramp-ch">%</span>
            <span className="as-ramp-ch">@</span>
          </div>
          <p className="as-ramp-cap" data-reveal="">
            <span lang="ko">왼쪽이 어둡고, 오른쪽이 밝다.</span> Left is dark, right
            is bright — ten glyphs are the whole palette.
          </p>
        </section>

        <footer className="as-foot" data-reveal="">
          <p className="as-foot__brand">
            ASCII <span lang="ko">아스키</span> ·{" "}
            <span lang="ko">문자로 그린 그림</span>
          </p>
          <p className="as-foot__line">
            <span lang="ko">순수 코드 — 이미지 없음.</span> Pure code · no
            images · MIT
          </p>
        </footer>
      </div>
      <div className="ascii-scan" aria-hidden="true" />
    </div>
  );
}

/* ==========================================================================
   ASCII 아스키 — pictures drawn in characters · no.064
   ascii-retrotech · terminal-black / phosphor-green · canvas density field
   Scoped by convention to .ascii-root; classes prefixed as- / ascii-.
   ========================================================================== */

.ascii-root {
  --as-bg: #020604;
  --as-deep: #010403;
  --as-panel: #04100a;
  --as-grid: rgba(94, 255, 160, 0.06);
  --as-grid-strong: rgba(94, 255, 160, 0.14);
  --as-text: #c8ffd9;
  --as-mute: #5e9e7a;
  --as-quiet: #2e5240;
  --as-green: #5effa0;
  --as-green-soft: rgba(94, 255, 160, 0.55);
  --as-font-display: "JetBrains Mono", ui-monospace, monospace;
  --as-font-kr: "Noto Sans KR", sans-serif;
  --as-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(94, 255, 160, 0.08), transparent 60%),
    radial-gradient(80% 60% at 50% 100%, rgba(94, 255, 160, 0.05), transparent 70%),
    linear-gradient(180deg, var(--as-deep) 0%, var(--as-bg) 50%, var(--as-deep) 100%);
  color: var(--as-text);
  font-family: var(--as-font-kr);
  font-weight: 400;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-x: clip;
}

.ascii-root :lang(ko) {
  font-family: var(--as-font-kr);
}

.ascii-root ::selection {
  background: var(--as-green);
  color: var(--as-deep);
}

.ascii-root :focus-visible {
  outline: 2px solid var(--as-green);
  outline-offset: 3px;
}

/* ---- Atmospheric depth: faint terminal grid behind all ---- */
.ascii-grid-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(var(--as-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--as-grid) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(110% 90% at 50% 40%, #000 30%, transparent 85%);
  -webkit-mask-image: radial-gradient(110% 90% at 50% 40%, #000 30%, transparent 85%);
}

.ascii-scan {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(120% 100% at 50% 50%, transparent 55%, rgba(1, 4, 3, 0.7) 100%);
}

.ascii-doc {
  position: relative;
  z-index: 2;
  max-width: 1100px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Reveal gating (JS-dependent pre-states) ---- */
.ascii-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--as-ease), transform 800ms var(--as-ease);
}
.ascii-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ---- Hero ---- */
.ascii-hero {
  padding: clamp(56px, 11vh, 110px) 0 clamp(28px, 5vh, 48px);
  text-align: center;
}
.as-kicker {
  margin: 0 0 clamp(18px, 4vh, 32px);
  font-family: var(--as-font-display);
  font-size: clamp(0.66rem, 0.9vw, 0.8rem);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--as-green);
  text-shadow: 0 0 10px var(--as-green-soft);
}
.as-title {
  margin: 0 0 14px;
  font-family: var(--as-font-display);
  font-weight: 700;
  font-size: clamp(3.2rem, 16vw, 13rem);
  line-height: 0.86;
  letter-spacing: -0.01em;
}
.as-title__row {
  display: block;
  /* The wordmark IS the concept: green fill with stacked green phosphor
     text-shadows — a real terminal tube blooming past its own edge. */
  color: var(--as-green);
  text-shadow:
    0 0 6px var(--as-green),
    0 0 16px var(--as-green-soft),
    0 0 32px rgba(94, 255, 160, 0.4);
}
.as-title__kr {
  display: block;
  margin-top: 6px;
  font-family: var(--as-font-kr);
  font-weight: 500;
  font-size: clamp(0.9rem, 2.4vw, 1.4rem);
  letter-spacing: 0.3em;
  color: var(--as-mute);
}
.as-sub {
  margin: 0 auto;
  max-width: 44ch;
  font-size: clamp(0.95rem, 1.2vw, 1.06rem);
  color: var(--as-mute);
}
.as-sub :lang(ko) {
  color: var(--as-text);
}
.as-ramp {
  font-family: var(--as-font-display);
  color: var(--as-green);
  background: rgba(94, 255, 160, 0.08);
  padding: 1px 6px;
  border-radius: 3px;
  text-shadow: 0 0 8px var(--as-green-soft);
}

/* ---- Glyph reveal (per-letter) ---- */
.ascii-glyph {
  display: inline-block;
}
.ascii-js .ascii-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  transition: opacity 700ms var(--as-ease), transform 700ms var(--as-ease);
  transition-delay: calc(var(--as-i) * 70ms + 150ms);
}
.ascii-js.is-mounted .ascii-glyph {
  opacity: 1;
  transform: none;
}

/* ---- Section headers ---- */
.as-sechead {
  text-align: center;
  margin-bottom: clamp(24px, 4vh, 40px);
}
.as-eyebrow {
  margin: 0 0 10px;
  font-family: var(--as-font-display);
  font-size: 0.66rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--as-green);
}
.as-secthead__title {
  margin: 0 0 8px;
  font-family: var(--as-font-display);
  font-weight: 700;
  font-size: clamp(1.7rem, 4vw, 2.6rem);
  text-transform: lowercase;
  letter-spacing: -0.01em;
  color: var(--as-text);
}
.as-secthead__kr {
  margin: 0;
  color: var(--as-mute);
  font-size: 0.98rem;
}

/* ---- The ASCII frames ---- */
.as-stage {
  padding: clamp(20px, 4vh, 40px) 0;
}
.as-frame {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
  padding: clamp(14px, 2vw, 22px);
  border: 1px solid var(--as-grid-strong);
  border-radius: 6px;
  background:
    radial-gradient(60% 80% at 50% 40%, rgba(94, 255, 160, 0.06), transparent 70%),
    linear-gradient(180deg, var(--as-panel), rgba(2, 6, 4, 0.8));
  overflow: hidden;
}
/* No-JS understudy <pre>: shown by default, hidden once the canvas draws. */
.as-understudy {
  position: relative;
  z-index: 1;
  margin: 0 0 10px;
  font-family: var(--as-font-display);
  font-size: clamp(0.5rem, 1.3vw, 0.82rem);
  line-height: 1.15;
  color: var(--as-green);
  white-space: pre;
  text-align: center;
  text-shadow:
    0 0 4px var(--as-green-soft),
    0 0 14px rgba(94, 255, 160, 0.3);
  opacity: 1;
  transition: opacity 400ms var(--as-ease);
}
.ascii-js .as-understudy {
  /* canvas takes over once JS is alive; understudy fades but stays in DOM as
     an accessible static fallback for no-canvas environments. */
  opacity: 0;
  position: absolute;
  inset: 0;
  margin: auto;
}
.as-canvas {
  position: relative;
  z-index: 2;
  display: block;
  width: 100%;
  height: clamp(180px, 32vh, 320px);
  margin: 0 auto;
}
.ascii-js .as-canvas {
  /* canvas sits on top of the faded understudy */
  margin-top: -100%;
}
.as-readout {
  position: relative;
  z-index: 3;
  margin: 12px 0 0;
  text-align: center;
  font-family: var(--as-font-display);
  font-size: 0.62rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--as-mute);
}

/* ---- The ramp explainer ---- */
.as-how {
  padding: clamp(20px, 4vh, 40px) 0;
}
.as-ramp-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(4px, 1.5vw, 16px);
  max-width: 640px;
  margin: 0 auto 18px;
  font-family: var(--as-font-display);
}
.as-ramp-ch {
  display: inline-grid;
  place-items: center;
  width: clamp(34px, 8vw, 60px);
  height: clamp(34px, 8vw, 60px);
  border: 1px solid var(--as-grid-strong);
  border-radius: 6px;
  font-size: clamp(1.1rem, 3vw, 1.8rem);
  color: var(--as-green);
  background: rgba(94, 255, 160, 0.05);
  text-shadow: 0 0 10px var(--as-green-soft);
}
.as-ramp-cap {
  margin: 0 auto;
  max-width: 42ch;
  text-align: center;
  font-size: 0.92rem;
  color: var(--as-mute);
}
.as-ramp-cap :lang(ko) {
  color: var(--as-text);
}

/* ---- Footer ---- */
.as-foot {
  margin-top: clamp(40px, 8vh, 80px);
  padding: clamp(28px, 5vh, 48px) 0;
  border-top: 1px solid var(--as-grid-strong);
  text-align: center;
}
.as-foot__brand {
  margin: 0 0 6px;
  font-family: var(--as-font-display);
  font-size: 0.8rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--as-text);
}
.as-foot__line {
  margin: 0;
  font-size: 0.78rem;
  color: var(--as-quiet);
}

/* ---- Reduced motion: renders hold a composed still, reveals sit ---- */
@media (prefers-reduced-motion: reduce) {
  .ascii-js [data-reveal],
  .ascii-js .ascii-glyph {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

@media (max-width: 560px) {
  .as-canvas { height: 200px; }
  .as-understudy { font-size: 0.42rem; }
}
